<?php
declare(strict_types=1);
namespace App\Controllers;
use App\Core\{Database,Request,Response,Session,View};use App\Models\Repositories\{CampaignRepository,ContactRepository,UserRepository};use App\Services\{ContactImporter,CpfCnpjValidator,Crypto};
final class AppController {private UserRepository $users;private ContactRepository $contacts;private CampaignRepository $campaigns;private array $config;
 public function __construct(){ $this->config=require dirname(__DIR__,2).'/config.php';$db=Database::connect($this->config);$this->users=new UserRepository($db);$this->contacts=new ContactRepository($db);$this->campaigns=new CampaignRepository($db);}
 private function csrf(Request $r):void{if(!Session::verifyCsrf($r->input('_csrf')))throw new \RuntimeException('Sessão expirada; recarregue a página.');} private function user():int{if(!($id=Session::userId()))Response::redirect('/login');return$id;} private function render(string $view,array $d=[]):never{View::render($view,$d+['csrf'=>Session::csrf(),'flash'=>Session::flash('message'),'userId'=>Session::userId()]);}
 public function home():never{$this->render('landing');} public function loginForm():never{$this->render('login');} public function registerForm():never{$this->render('register');}
 public function register(Request $r):never{$this->csrf($r);$name=trim((string)$r->input('name'));$email=strtolower(trim((string)$r->input('email')));$pass=(string)$r->input('password');$type=(string)$r->input('person_type');$doc=(string)$r->input('document');if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<8||$pass!==$r->input('password_confirmation')||!(new CpfCnpjValidator())->valid($doc,$type)){Session::flash('message','Revise os dados: senha mínima de 8 caracteres e CPF/CNPJ válido.');Response::redirect('/cadastro');}$crypto=new Crypto($this->config['app']['encryption_key']);try{$id=$this->users->create(['name'=>$name,'email'=>$email,'password'=>password_hash($pass,PASSWORD_BCRYPT),'phone'=>trim((string)$r->input('phone')),'type'=>$type,'cipher'=>$crypto->encrypt(preg_replace('/\D/','',$doc)),'hash'=>hash('sha256',preg_replace('/\D/','',$doc))]);Session::flash('message','Cadastro criado. Configure SMTP e assinatura após a ativação por e-mail (modo local: conta pendente).');}catch(\Throwable){Session::flash('message','E-mail ou documento já cadastrado.');}Response::redirect('/login');}
 public function login(Request $r):never{$this->csrf($r);$u=$this->users->findByEmail(strtolower(trim((string)$r->input('email'))));if(!$u||!password_verify((string)$r->input('password'),$u['password_hash'])){Session::flash('message','Credenciais inválidas.');Response::redirect('/login');}Session::login((int)$u['id']);Response::redirect('/painel');}
 public function logout():never{Session::logout();Response::redirect('/');} public function dashboard():never{$id=$this->user();$this->render('dashboard',['stats'=>$this->contacts->stats($id),'campaigns'=>$this->campaigns->list($id),'subscribed'=>$this->users->activeSubscription($id)]);}
 public function contacts():never{$id=$this->user();$this->render('contacts',['data'=>$this->contacts->list($id,(string)($_GET['q']??''),(int)($_GET['p']??1))]);}
 public function import(Request $r):never{$id=$this->user();$this->csrf($r);$content=(string)$r->input('emails');$source='manual';if(($f=$r->files('file'))&&$f['error']===UPLOAD_ERR_OK&&$f['size']<=5*1024*1024){$content=(new ContactImporter())->readFile($f['tmp_name'],pathinfo($f['name'],PATHINFO_EXTENSION));$source='file';}$res=(new ContactImporter())->extract($content);[$add,$sup]=$this->contacts->addMany($id,$res['emails'],$source);Session::flash('message',"Importação: {$add} adicionados, {$res['duplicates']} duplicados, {$sup} bloqueados.");Response::redirect('/contatos');}
 public function deleteContact(Request $r):never{$id=$this->user();$this->csrf($r);$this->contacts->delete((int)$r->input('id'),$id);Response::redirect('/contatos');}
 public function campaignForm():never{$this->user();$this->render('campaign');} public function campaignCreate(Request $r):never{$id=$this->user();$this->csrf($r);$c=$this->campaigns->create($id,['title'=>trim((string)$r->input('title')),'subject'=>trim((string)$r->input('subject')),'body'=>(string)$r->input('body'),'links'=>['site'=>$r->input('site'),'instagram'=>$r->input('instagram'),'linkedin'=>$r->input('linkedin'),'facebook'=>$r->input('facebook')]]);Session::flash('message',"Rascunho #{$c} salvo.");Response::redirect('/painel');}
 public function campaignFinalize(Request $r):never{$u=$this->user();$this->csrf($r);$settings=$this->config['app']['default_hourly_limit']??30;$this->campaigns->finalize((int)$r->input('id'),$u,(int)$settings);Session::flash('message','Campanha enfileirada.');Response::redirect('/painel');}
 public function campaignStatus(Request $r):never{$u=$this->user();$this->campaigns->setStatus((int)$r->input('id'),$u,(string)$r->input('status'));Response::redirect('/painel');}
 public function optoutForm(Request $r):never{$token=(string)$r->input('token');$c=$this->contacts->byToken($token);$this->render('optout',['token'=>$token,'email'=>$c?preg_replace('/(?<=^.{2}).(?=[^@]*@)/','*',$c['email']):'']);}public function optout(Request $r):never{$this->csrf($r);$out=$this->contacts->optOut((string)$r->input('token'),trim((string)$r->input('reason'))?:null);$this->render('optout_done',['status'=>$out]);}
}
